{"results": [{"id": "FAM:SF-APPS-073", "label": "Study family SF-APPS-073: Persistent Impact Score lag curves (global then within-team)", "score": 1.787, "reached_via": ["request matches the question or hypothesis of FAM:SF-APPS-073 (0.85)"], "attributes": {"observed_research_question": "Persistent Impact Score lag curves (global then within-team)", "auto_outcome_status": "artifact", "observed_hypothesis": "Running play type X raises the same team's next 1-5 possession PPP vs a matched baseline (action memory).", "observed_result": "Global horizons: DRIVE/SPOT_UP/TRANSITION=5; others 0 (PNR/CUT/POST_UP/PUTBACK). SPOT_UP lag-1 lift +0.027 ctrl_p=0.0000. Within-team: all horizons 0 except SPOT_UP horizon(all)=1; PNR lag-1 within_team_lift=-0.0218.", "auto_failure_mechanism": "C_artifact (apparent effect produced by a construction, selection or labelling flaw)", "observed_failure_evidence": "Flat non-decaying global lifts disappear after team-season demeaning; remaining within-team memory is essentially none except SPOT_UP lag-1.", "observed_sample_and_power": "DRIVE lag-1 n=163696; SPOT_UP n=175021", "auto_validation_status": "no_validation_recorded; evidence: NOT_RECORDED"}, "relationships": [{"rel": "auto_related_family", "node": "FAM:SF-APPS-059"}]}, {"id": "FAM:SF-CHT-029", "label": "Study family SF-CHT-029: Persistent Impact Score Level 1 gate", "score": 1.787, "reached_via": ["request matches the question or hypothesis of FAM:SF-CHT-029 (0.82)"], "attributes": {"observed_research_question": "Persistent Impact Score Level 1 gate", "auto_outcome_status": "artifact", "observed_hypothesis": "Play-type actions have decaying cross-possession memory (lag-1 effect >= lag-2; not just score margin or team quality).", "observed_result": "FAIL decay-sanity: DRIVE lifts +0.015,+0.020,+0.018,+0.021,+0.020 (flat). Within-team: DRIVE lag-1 +0.015 to -0.002. Cohen d ~0.01-0.03; p~0 from n>150k. Callable play-type horizons = 0.", "auto_failure_mechanism": "C_artifact (apparent effect produced by a construction, selection or labelling flaw)", "observed_failure_evidence": "Flat non-decaying lifts collapse under within-team baseline; team-quality confound.", "observed_sample_and_power": "n>150k per lag; 915,570 possessions", "auto_validation_status": "no_validation_recorded; evidence: NOT_RECORDED", "observed_verdict": "failed_gate"}, "relationships": [{"rel": "auto_limited_by", "node": "LIM:confounding"}, {"rel": "auto_has_risk", "node": "RISK:CONFOUNDING"}, {"rel": "auto_related_family", "node": "FAM:SF-APPS-073"}]}, {"id": "FAM:SF-APPS-075", "label": "Study family SF-APPS-075: Extended Possession Value (direct PPP + opponent T+1 suppression)", "score": 0.943, "reached_via": ["request matches the question or hypothesis of FAM:SF-APPS-075 (0.83)"], "attributes": {"observed_research_question": "Extended Possession Value (direct PPP + opponent T+1 suppression)", "auto_outcome_status": "not a hypothesis test", "observed_hypothesis": "Play types and players have a real downstream (opponent next-PPP) component beyond direct PPP.", "observed_result": "4/8 PTs downstream real: CUT Ext 1.658 (supp +0.0220), TRANSITION 1.509 (+0.0145), SPOT_UP 1.303 (+0.0124), POST_UP 1.127 (+0.0194). DRIVE downstream not real (opp ATT +0.0024). Player downstream mostly BH ns except M. M [cut; read_family for the full text]", "auto_failure_mechanism": "E_unclear (mechanism unclear from the records)", "observed_failure_evidence": "Downstream effects are small (~0.01-0.02 PPP) relative to direct PPP gaps; player list is mostly non-FINDING after BH.", "observed_sample_and_power": "PT-level n in the tens to hundreds of thousands implied by other seq files"}, "relationships": [{"rel": "auto_related_family", "node": "FAM:SF-APPS-049"}, {"rel": "auto_related_family", "node": "FAM:SF07"}]}, {"id": "FAM:SF-APPM-014", "label": "Study family SF-APPM-014: Play-type label accuracy / distribution audit", "score": 0.923, "reached_via": ["request matches the question or hypothesis of FAM:SF-APPM-014 (0.81)"], "attributes": {"observed_research_question": "Play-type label accuracy / distribution audit", "auto_outcome_status": "not a hypothesis test", "observed_hypothesis": "Inferred play-type labels match benchmark volumes, foul rates, PPP and known team identities.", "observed_result": "Audit overall FAIL: OTHER 20.2% vs <10% target; 40.8% low confidence; DRIVE foul-draw 1.7% vs 14-22% benchmark; most PTs PPP above benchmark band; MIA identity checks fail.", "auto_failure_mechanism": "C_artifact (apparent effect produced by a construction, selection or labelling flaw)", "observed_failure_evidence": "'play type labels have systematic issues that undermine adaptation findings'; foul possessions leak into OTHER.", "observed_verdict": "tool_eval_fail"}, "relationships": [{"rel": "auto_limited_by", "node": "LIM:label_or_classification_error"}, {"rel": "auto_limited_by", "node": "LIM:leakage"}, {"rel": "auto_limited_by", "node": "LIM:small_sample"}, {"rel": "auto_has_risk", "node": "RISK:LABEL_ERROR"}, {"rel": "auto_has_risk", "node": "RISK:LEAKAGE_LOOKAHEAD"}, {"rel": "auto_has_risk", "node": "RISK:SAMPLE_SIZE_POWER"}]}, {"id": "FAM:SF-CHT-086", "label": "Study family SF-CHT-086: LLM / ex-ante usefulness of suppression context (leakage audit)", "score": 0.607, "reached_via": ["request matches RQC:RQC-109 (0.78); FAM:SF-CHT-086 auto_addresses_question RQC:RQC-109"], "attributes": {"observed_research_question": "LLM / ex-ante usefulness of suppression context (leakage audit)", "auto_outcome_status": "artifact", "observed_hypothesis": "An LLM layer can reason about suppression context beyond the engine, or predicting suppression from H1 is a viable label.", "observed_result": "Label is mostly an RTM artifact. Apparent LLM skill was leakage; what survives is small/noisy; engine misses are selection/override not missing graph facts. Margin of LLM vs engine described as literally zero after leaka [cut; read_family for the full text]", "auto_failure_mechanism": "C_artifact (apparent effect produced by a construction, selection or labelling flaw)", "observed_failure_evidence": "Suppression label selected on the outcome; remaining LLM edge not statistically retrievable."}, "relationships": [{"rel": "auto_limited_by", "node": "LIM:label_or_classification_error"}, {"rel": "auto_has_risk", "node": "RISK:LABEL_ERROR"}, {"rel": "auto_has_risk", "node": "RISK:RTM_SELECTION"}, {"rel": "auto_related_family", "node": "FAM:SF-APPA-005"}]}, {"id": "FAM:SF-APPS-049", "label": "Study family SF-APPS-049: 52-series sequential adaptation: durable pivot branches and net swing", "score": 0.529, "reached_via": ["FAM:SF-APPS-075 auto_related_family (record_link_related_to) FAM:SF-APPS-049", "request matches DS:Play_type_initiation_records_Neo4j_INITIATED_edges_play_type_possessions (0.76); FAM:SF-APPS-049 auto_uses_dataset DS:Play_type_initiation_records_Neo4j_INITIATED_edges_play_type_possessions"], "attributes": {"observed_research_question": "52-series sequential adaptation: durable pivot branches and net swing", "auto_outcome_status": "rejected", "observed_hypothesis": "If-X-fails-then-Y pivot branches and PT net-swing (own PPP - opp next PPP) are durable across ~104 playoff team-offense units.", "observed_result": "durable_branches=[]. Median net swing: CUT +0.36 (neg in 9%), TRANSITION +0.26 (21%), PULL_UP +0.09 (33%), PNR +0.04 (45%), SPOT_UP +0.02 (40%), POST_UP -0.22 (77%), DRIVE -0.27 (88%). n_units: CUT 103, DRIVE/POST_UP/SPO [cut; read_family for the full text]", "auto_failure_mechanism": "B_powered_null (adequately powered null result)", "observed_failure_evidence": "No conditional pivot branch met the durability bar (empty durable_branches). DRIVE/POST_UP negative net swing is the durable aftershock finding, recorded here as the positive half of the same run.", "observed_sample_and_power": "52 series, 104 units"}, "relationships": [{"rel": "auto_related_family", "node": "FAM:SF-APPM-011"}]}, {"id": "FAM:SF07", "label": "Study family SF07: Sequential pair premium and defensive aftershock (8/8 PTs)", "score": 0.529, "reached_via": ["FAM:SF-APPS-075 auto_related_family (record_link_related_to) FAM:SF07", "request matches DS:Play_type_initiation_records_Neo4j_INITIATED_edges_play_type_possessions (0.76); FAM:SF07 auto_uses_dataset DS:Play_type_initiation_records_Neo4j_INITIATED_edges_play_type_possessions"], "attributes": {"observed_research_question": "Sequential pair premium and defensive aftershock (8/8 PTs)", "auto_outcome_status": "supported", "observed_hypothesis": "After the opponent runs play type X, the next offensive play type Y scores above Y's unconditional H2 baseline, and every PT has a defensive aftershock.", "observed_result": ["[APPA-049] A2 aftershock 8/8 PTs replicate all-games and playoffs (CUT +0.119 n=21,398 / PO +0.131 n=1,145 through TRANSITION +0.135 n=26,262 / +0.126 n=1,529). Top pair premiums: PUTBACK->TRANSITION +0.084 n=565; CUT->P [cut; read_family for the full text]", "[APPS-037] All-games aftershock after success: CUT +0.119 (n=21398), DRIVE +0.123 (57621), PNR +0.127 (51194), POST_UP +0.128 (20619), PULL_UP +0.132 (26060), PUTBACK +0.130 (5888), SPOT_UP +0.128 (43857), TRANSITION +0. [cut; read_family for the full text]"], "auto_failure_mechanism": "D_positive (no failure: positive result)"}, "relationships": [{"rel": "auto_limited_by", "node": "LIM:small_sample"}]}, {"id": "FAM:SF30", "label": "Study family SF30: Brown-initiated possession -> Tatum next-possession ATT", "score": 0.529, "reached_via": ["FAM:SF-APPS-075 auto_related_family (record_link_related_to) FAM:SF30", "request matches DS:Play_type_initiation_records_Neo4j_INITIATED_edges_play_type_possessions (0.76); FAM:SF30 auto_uses_dataset DS:Play_type_initiation_records_Neo4j_INITIATED_edges_play_type_possessions"], "attributes": {"observed_research_question": "Brown-initiated possession -> Tatum next-possession ATT", "auto_outcome_status": "inconclusive", "observed_hypothesis": "A Jaylen Brown-initiated BOS possession raises Tatum's points on the next BOS possession (spillover/gravity).", "observed_result": ["[APPS-065] PSM ATT=-0.0165, bootstrap 95% CI [-0.0924,+0.0605]. Exact-match ATT=-0.0857. Stratified perm p=0.0275 on ATT=-0.0171. Placebo 95% [-0.0762,+0.0730]; real ATT inside. Playoffs ATT=+0.0485 CI[-0.1095,+0.2078].", "[CHT-030] Def A ATT -0.017, bootstrap CI [-0.092, +0.061], perm p=0.028. Def B ATT -0.077, CI [-0.146, -0.001]. Placebo mean ~0; real ATT inside placebo 95% range both defs. Signs flip across quarters/RS-PO."], "auto_failure_mechanism": "none (no failure recorded)", "observed_sample_and_power": "[APPS-065] treated n=1173"}, "relationships": [{"rel": "auto_has_risk", "node": "RISK:PLACEBO_DEPENDENCE"}, {"rel": "auto_has_risk", "node": "RISK:SAMPLE_SIZE_POWER"}, {"rel": "auto_related_family", "node": "FAM:SF-APPS-066"}]}, {"id": "FAM:SF-APPM-058", "label": "Study family SF-APPM-058: PNR shot-level season rates vs possession labels", "score": 0.519, "reached_via": ["FAM:SF-APPM-014 auto_related_family (record_link_related_to) FAM:SF-APPM-058", "request matches DS:Play_type_initiation_records_Neo4j_INITIATED_edges_play_type_possessions (0.76); FAM:SF-APPM-058 auto_uses_dataset DS:Play_type_initiation_records_Neo4j_INITIATED_edges_play_type_possessions"], "attributes": {"observed_research_question": "PNR shot-level season rates vs possession labels", "auto_outcome_status": "not a hypothesis test", "observed_hypothesis": "PBP-derived shot-level PNR rates sit in a realistic band (script notes possession-level rates will be higher) and vary by team as expected.", "observed_result": "2024-25 shot-level PNR share of half-court shots ranges from OKC 7.567% (498/6581) and BOS 7.854% to IND 13.824% (856/6192) and NYK 11.959%. ATL 11.361%, DEN 11.404%, PHX 10.232% (bh 7.050 / roll 3.181).", "auto_failure_mechanism": "E_unclear (mechanism unclear from the records)", "observed_failure_evidence": "No pass/fail gate in the output; rates are a calibration input for PBPProxyPNR (later logs show calibrated PNR ~17.9-19.6% of possessions).", "observed_sample_and_power": "30 teams, half_court_shots ~5994-6581", "auto_validation_status": "no_validation_recorded; evidence: NOT_RECORDED"}, "relationships": [{"rel": "auto_related_family", "node": "FAM:SF-APPM-014"}]}, {"id": "FAM:SF-APPA-050", "label": "Study family SF-APPA-050: Superstar sequential suppression: opponent play before the star", "score": 0.486, "reached_via": ["request matches RQC:RQC-018 (0.74); FAM:SF-APPA-050 auto_addresses_question RQC:RQC-018", "request matches DS:Play_type_initiation_records_Neo4j_INITIATED_edges_play_type_possessions (0.76); FAM:SF-APPA-050 auto_uses_dataset DS:Play_type_initiation_records_Neo4j_INITIATED_edges_play_type_possessions"], "attributes": {"observed_research_question": "Superstar sequential suppression: opponent play before the star", "auto_outcome_status": "not a hypothesis test", "observed_hypothesis": "A specific opponent play type on the preceding possession suppresses each star's next-possession PPP relative to that star's baseline.", "observed_result": "PUTBACK is top suppressor for 6+ stars (e.g. D. Mitchell 1.178 to 0.884, d=-0.294, n_after=95; B. Beal d=-0.345 n=32; C. Holmgren d=-0.222 n=52). Other tops: TRANSITION (A. Davis -0.058), POST_UP (N. Jokic -0.075), PULL_ [cut; read_family for the full text]", "auto_failure_mechanism": "E_unclear (mechanism unclear from the records)", "observed_failure_evidence": "No multiplicity correction; n_after is 32-95 for several PUTBACK cells vs thousands of baseline possessions.", "observed_sample_and_power": "30 stars; min n_after=30", "auto_validation_status": "no_validation_recorded; evidence: NOT_RECORDED"}, "relationships": [{"rel": "auto_has_risk", "node": "RISK:DRIFT_NONSTATIONARITY"}]}], "n_results": 10}

